/**
 * A stand-in for Python's immutable `bytes` object.
 *
 * The payload is kept as a plain array of integers in the range 0-255 so that
 * the bencode codec can work on byte values directly while still printing
 * exactly what CPython's `repr()` would print.
 */

export class PyBytes {
  /** @param {number[]} values byte values, 0-255 */
  constructor(values = []) {
    this.values = values;
  }

  get length() {
    return this.values.length;
  }

  /** Byte value at `index`. */
  at(index) {
    return this.values[index];
  }

  slice(start, end) {
    return new PyBytes(this.values.slice(start, end));
  }

  /** Decodes as Latin-1, which is only ever used for internal comparisons. */
  toLatin1String() {
    let out = '';
    for (const value of this.values) out += String.fromCharCode(value);
    return out;
  }
}

export function isPyBytes(value) {
  return value instanceof PyBytes;
}

/** Builds a `PyBytes` from a string whose code points are all below 256. */
export function bytesFromLatin1(text) {
  const values = [];
  for (let i = 0; i < text.length; i += 1) values.push(text.charCodeAt(i) & 0xff);
  return new PyBytes(values);
}

/** Concatenates several `PyBytes` into one. */
export function concatBytes(chunks) {
  const values = [];
  for (const chunk of chunks) {
    for (const value of chunk.values) values.push(value);
  }
  return new PyBytes(values);
}

/** Raised in place of Python's `UnicodeEncodeError`. */
export class UnicodeEncodeError extends Error {
  constructor(encoding, start, end, reason, charDisplay) {
    const subject =
      end - start > 1
        ? `characters in position ${start}-${end - 1}`
        : `character ${charDisplay} in position ${start}`;
    super(`'${encoding}' codec can't encode ${subject}: ${reason}`);
    this.name = 'UnicodeEncodeError';
    this.encoding = encoding;
    this.start = start;
    this.end = end;
  }
}

/** Renders a code point the way CPython names it inside encoder errors. */
function codePointDisplay(codePoint) {
  if (codePoint <= 0xff) {
    return `'\\x${codePoint.toString(16).padStart(2, '0')}'`;
  }
  if (codePoint <= 0xffff) {
    return `'\\u${codePoint.toString(16).padStart(4, '0')}'`;
  }
  return `'\\U${codePoint.toString(16).padStart(8, '0')}'`;
}

/**
 * `str.encode('ascii')`.
 *
 * Throws `UnicodeEncodeError` naming the first maximal run of non-ASCII code
 * points, with positions counted in code points just like CPython.
 */
export function encodeAscii(text) {
  const codePoints = Array.from(text, (ch) => ch.codePointAt(0));
  const values = [];
  for (let index = 0; index < codePoints.length; index += 1) {
    const codePoint = codePoints[index];
    if (codePoint > 0x7f) {
      let end = index + 1;
      while (end < codePoints.length && codePoints[end] > 0x7f) end += 1;
      throw new UnicodeEncodeError(
        'ascii',
        index,
        end,
        'ordinal not in range(128)',
        codePointDisplay(codePoint),
      );
    }
    values.push(codePoint);
  }
  return new PyBytes(values);
}

