 *   - `\x1c`-`\x1f` and `\x85` are whitespace for Python and *not* for JS.
 */
const PY_SPACE_EXTRA = '';

export function isPySpace(ch) {
  if (ch === '﻿') return false;
  if (PY_SPACE_EXTRA.includes(ch)) return true;
  return /\s/.test(ch);
}

/** Strips leading and trailing Python whitespace, as `int(str)` does. */
export function stripPySpace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isPySpace(text[start])) start += 1;
  while (end > start && isPySpace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

const DECIMAL_DIGIT = /\p{Nd}/u;

/**
 * Numeric value of a decimal-digit code point, or -1 when the character is
 * not in the Nd category.
 *
 * Every Nd block is a run of exactly ten consecutive code points that starts
 * at the block's zero digit, and blocks are never adjacent to one another, so
 * walking backwards to the start of the run recovers the block base without
 * needing a table of every block.
 */
export function decimalDigitValue(codePoint) {
  const ch = String.fromCodePoint(codePoint);
  if (!DECIMAL_DIGIT.test(ch)) return -1;
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  let base = codePoint;
  while (
    base > 0 &&
    codePoint - base < 9 &&
    DECIMAL_DIGIT.test(String.fromCodePoint(base - 1))
  ) {
    base -= 1;
  }
  return codePoint - base;
}

/** True when `repr()` would leave the character as-is rather than escaping it. */
export function isPyPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  const ch = String.fromCodePoint(codePoint);
  // Python escapes anything in the Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs
  // categories (space itself being the single exception handled above).
  return !/[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u.test(ch);
}

