/**
 * Python's `int(str)` conversion.
 *
 * Values are carried as `BigInt` because Python integers are unbounded — the
 * script happily round-trips values far past `Number.MAX_SAFE_INTEGER`.
 */

import { stripPySpace, decimalDigitValue } from './chars.mjs';

/** Raised in place of Python's `ValueError`. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export function isPyInt(value) {
  return typeof value === 'bigint';
}

/**
 * Converts `text` to a `BigInt` using base-10 `int()` rules: surrounding
 * whitespace is ignored, an optional sign may lead, digits come from any
 * Unicode decimal-digit block, and single underscores may separate digits.
 */
export function pyIntFromString(text) {
  const invalid = () =>
    new PyValueError(`invalid literal for int() with base 10: ${strLiteral(text)}`);

  const body = stripPySpace(text);
  const chars = Array.from(body);
  let index = 0;

  let negative = false;
  if (chars[index] === '+' || chars[index] === '-') {
    negative = chars[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < chars.length; index += 1) {
    const ch = chars[index];
    if (ch === '_') {
      // Underscores are only legal between two digits.
      if (!previousWasDigit) throw invalid();
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch.codePointAt(0));
    if (value < 0) throw invalid();
    digits += String(value);
    previousWasDigit = true;
  }

  if (!previousWasDigit) throw invalid();
  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/**
 * `repr()` of a `str`. Needed because argparse reports the offending value
 * with `%r` when a type conversion fails.
 */
function strLiteral(text) {
  // Imported lazily-by-hand to keep this module free of a cycle with repr.mjs.
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote || ch === '\\') out += `\\${ch}`;
    else out += ch;
  }
  return out + quote;
}

