/**
 * The escaping half of Python's `repr()` for `str` and `bytes`.
 *
 * Kept separate from `repr.mjs` so that `int.mjs` can format `ValueError`
 * messages without creating an import cycle.
 */

import { isPyPrintable } from './chars.mjs';

/**
 * Python prefers a single quote and only switches to a double quote when the
 * text contains a single quote but no double quote.
 */
function chooseQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? '"' : "'";
}

const SHORT_ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/** `\xNN`, `\uNNNN` or `\UNNNNNNNN`, whichever is the shortest that fits. */
function hexEscape(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/** `repr()` of a `bytes` object, e.g. `b'l4:utf8i1eli1eee'`. */
export function pyBytesRepr(pyBytes) {
  const { values } = pyBytes;
  const quote = chooseQuote(values.includes(0x27), values.includes(0x22));
  const quoteByte = quote.charCodeAt(0);

  let out = `b${quote}`;
  for (const value of values) {
    if (value === quoteByte) out += `\\${quote}`;
    else if (SHORT_ESCAPES.has(value)) out += SHORT_ESCAPES.get(value);
    else if (value < 0x20 || value >= 0x7f) out += hexEscape(value);
    else out += String.fromCharCode(value);
  }
  return out + quote;
}

/** `repr()` of a `str` object. */
export function pyStrRepr(text) {
  const quote = chooseQuote(text.includes("'"), text.includes('"'));

  let out = quote;
  for (const ch of text) {
    const codePoint = ch.codePointAt(0);
    if (ch === quote) out += `\\${quote}`;
    else if (SHORT_ESCAPES.has(codePoint)) out += SHORT_ESCAPES.get(codePoint);
    else if (!isPyPrintable(codePoint)) out += hexEscape(codePoint);
    else out += ch;
  }
  return out + quote;
}

