/**
 * Bencode decoder.
 *
 * Mirrors the encoder: byte strings come back as `PyBytes`, integers as
 * `BigInt`, lists as arrays, and dictionaries as `Map`s keyed by `PyBytes`.
 */

import { PyBytes } from '../pytypes/bytes.mjs';

/** Raised for input that is not well-formed bencode. */
export class BencodeDecodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BencodeDecodeError';
  }
}

const DIGIT_ZERO = 0x30;
const DIGIT_NINE = 0x39;
const COLON = 0x3a;
const MINUS = 0x2d;
const END = 0x65; // 'e'
const INT_START = 0x69; // 'i'
const LIST_START = 0x6c; // 'l'
const DICT_START = 0x64; // 'd'

function isDigit(byte) {
  return byte >= DIGIT_ZERO && byte <= DIGIT_NINE;
}

/**
 * Reads the decimal run starting at `start` and stops at `terminator`.
 *
 * @returns {[bigint, number]} the value and the index just past the terminator
 */
function readSignedDecimal(data, start, terminator) {
  let index = start;
  let digits = '';

  if (data.at(index) === MINUS) {
    digits += '-';
    index += 1;
  }
  while (index < data.length && isDigit(data.at(index))) {
    digits += String.fromCharCode(data.at(index));
    index += 1;
  }
  if (data.at(index) !== terminator) {
    throw new BencodeDecodeError(`Malformed number at position ${start}`);
  }
  if (digits === '' || digits === '-') {
    throw new BencodeDecodeError(`Missing digits at position ${start}`);
  }
  return [BigInt(digits), index + 1];
}

function decodeValue(data, position) {
  if (position >= data.length) {
    throw new BencodeDecodeError('Unexpected end of input');
  }
  const marker = data.at(position);

  if (marker === INT_START) {
    return readSignedDecimal(data, position + 1, END);
  }
  if (marker === LIST_START) {
    const items = [];
    let cursor = position + 1;
    while (cursor < data.length && data.at(cursor) !== END) {
      const [item, next] = decodeValue(data, cursor);
      items.push(item);
      cursor = next;
    }
    if (cursor >= data.length) {
      throw new BencodeDecodeError('Unterminated list');
    }
    return [items, cursor + 1];
  }
  if (marker === DICT_START) {
    const entries = new Map();
    let cursor = position + 1;
    while (cursor < data.length && data.at(cursor) !== END) {
      const [key, afterKey] = decodeValue(data, cursor);
      if (!(key instanceof PyBytes)) {
        throw new BencodeDecodeError(`Dictionary key at ${cursor} is not a byte string`);
      }
      const [item, afterValue] = decodeValue(data, afterKey);
      entries.set(key, item);
      cursor = afterValue;
    }
    if (cursor >= data.length) {
      throw new BencodeDecodeError('Unterminated dictionary');
    }
    return [entries, cursor + 1];
  }
  if (isDigit(marker)) {
    const [length, afterLength] = readSignedDecimal(data, position, COLON);
    const end = afterLength + Number(length);
    if (end > data.length) {
      throw new BencodeDecodeError(`Byte string at ${position} runs past end of input`);
    }
    return [data.slice(afterLength, end), end];
  }
  throw new BencodeDecodeError(
    `Unexpected marker '${String.fromCharCode(marker)}' at position ${position}`,
  );
}

/**
 * Decodes a complete bencoded `PyBytes`.
 *
 * @param {PyBytes} data
 * @returns {PyBytes|bigint|Array|Map}
 */
export function decode(data) {
  const [value, consumed] = decodeValue(data, 0);
  if (consumed !== data.length) {
    throw new BencodeDecodeError(`Trailing data at position ${consumed}`);
  }
  return value;
}

