/**
 * Error types used by the CLI layer.
 */

/** Python's `SystemExit`, raised by `parser.error()` and `--help`. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * argparse's `ArgumentError`: an error tied to a specific action, rendered as
 * `argument <name>: <message>`.
 */
export class ArgumentError extends Error {
  constructor(actionName, message) {
    super(actionName === null ? message : `argument ${actionName}: ${message}`);
    this.name = 'ArgumentError';
  }
}

