/**
 * A faithful-enough `argparse.ArgumentParser` for this program's interface:
 * two required options taking one value each, plus the automatic `-h/--help`.
 *
 * The behaviours that matter for output parity, all verified against the
 * reference build:
 *   - `--opt value` and `--opt=value` are both accepted
 *   - unambiguous long-option prefixes are accepted (`--he` -> `--help`)
 *   - a later occurrence of an option overwrites an earlier one
 *   - tokens are classified as option-vs-value in one pass up front, so
 *     `--a -x` fails with "expected one argument" while `--a -5` succeeds
 *   - missing required options are reported before unrecognized ones
 *   - errors print usage plus `prog: error: ...` on stderr and exit 2
 */

import { basename } from 'node:path';
import { pyStrRepr } from '../pytypes/escape.mjs';
import { pyIntFromString, PyValueError } from '../pytypes/int.mjs';
import { ArgumentError, SystemExit } from './errors.mjs';
import { printLine, writeStdout, writeStderr } from './io.mjs';

const PREFIX_CHARS = '-';
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
const MAX_HELP_POSITION = 24;
const INDENT = 2;

/** argparse's `type=int`, reported as `int` in error messages. */
export const INT_TYPE = { name: 'int', convert: pyIntFromString };

/** argparse's `type=str`, which is the identity conversion. */
export const STR_TYPE = { name: 'str', convert: (text) => text };

class Action {
  constructor({ optionStrings, dest, type, required, nargs, help }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.nargs = nargs;
    this.help = help;
    this.metavar = dest.toUpperCase();
  }

  /** `_get_action_name`: how the action is named inside error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** `--a A`, or `-h, --help` for the flag that takes no value. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${this.metavar}`).join(', ');
  }

  /** How the action appears inside the usage line. */
  formatUsage() {
    const primary = this.optionStrings[0];
    const body = this.nargs === 0 ? primary : `${primary} ${this.metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    // argparse defaults prog to the basename of the script being run.
    this.prog = prog ?? basename(process.argv[1] ?? 'test6.mjs');
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument('-h', '--help', {
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * `add_argument`. Accepts one or more option strings followed by an options
   * object; `dest` is derived from the first long option, as argparse does.
   */
  addArgument(...args) {
    const config = typeof args[args.length - 1] === 'object' ? args.pop() : {};
    const optionStrings = args;
    const longest = optionStrings.find((option) => option.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');

    const action = new Action({
      optionStrings,
      dest,
      type: config.type ?? STR_TYPE,
      required: config.required ?? false,
      nargs: config.nargs ?? 1,
      help: config.help ?? null,
    });

    this.actions.push(action);
    for (const option of optionStrings) this.optionStringActions.set(option, action);
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsage());
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => action.formatInvocation());
    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    let out = `${this.formatUsage()}\noptions:\n`;
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (!action.help) {
        out += `${' '.repeat(INDENT)}${invocation}\n`;
        return;
      }
      if (invocation.length <= actionWidth) {
        out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
        out += `${' '.repeat(INDENT)}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    });
    return out;
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** `parser.error()`: usage plus message on stderr, then exit status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * `_parse_optional`: decides whether a token is an option, and if so which
   * action it names and whether a value was glued on with `=`.
   */
  classifyToken(token) {
    if (token === '') return { kind: 'value' };
    if (!PREFIX_CHARS.includes(token[0])) return { kind: 'value' };

    const exact = this.optionStringActions.get(token);
    if (exact) return { kind: 'option', action: exact, optionString: token, explicitArg: null };

    // A lone "-" is a positional by convention.
    if (token.length === 1) return { kind: 'value' };

    if (token.includes('=')) {
      const separator = token.indexOf('=');
      const optionString = token.slice(0, separator);
      const action = this.optionStringActions.get(optionString);
      if (action) {
        return { kind: 'option', action, optionString, explicitArg: token.slice(separator + 1) };
      }
    }

    const matches = this.matchAbbreviation(token);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    // Negative numbers are values as long as no option looks like one.
    if (NEGATIVE_NUMBER.test(token)) return { kind: 'value' };
    if (token.includes(' ')) return { kind: 'value' };

    return { kind: 'unknown-option' };
  }

  /** `_get_option_tuples`: long options may be abbreviated to a unique prefix. */
  matchAbbreviation(token) {
    if (!(PREFIX_CHARS.includes(token[0]) && PREFIX_CHARS.includes(token[1]))) return [];

    const separator = token.indexOf('=');
    const prefix = separator === -1 ? token : token.slice(0, separator);
    const explicitArg = separator === -1 ? null : token.slice(separator + 1);

    const matches = [];
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(prefix)) {
        matches.push({ kind: 'option', action, optionString, explicitArg });
      }
    }
    return matches;
  }

  /** Runs an action's `type` callable, wrapping failures the way argparse does. */
  convert(action, rawValue) {
    try {
      return action.type.convert(rawValue);
    } catch (cause) {
      if (cause instanceof PyValueError) {
        throw new ArgumentError(
          action.name,
          `invalid ${action.type.name} value: ${pyStrRepr(rawValue)}`,
        );
      }
      throw cause;
    }
  }

  parseKnownArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.nargs !== 0) namespace[action.dest] = null;
    }

    // First pass: classify every token. Everything after a bare "--" is a
    // value, and the "--" itself stays behind as an extra.
    const tokens = [];
    let afterSeparator = false;
    for (const token of argv) {
      if (!afterSeparator && token === '--') {
        afterSeparator = true;
        tokens.push({ token, info: { kind: 'separator' } });
        continue;
      }
      const info = afterSeparator ? { kind: 'value' } : this.classifyToken(token);
      tokens.push({ token, info });
    }

    const seen = new Set();
    const extras = [];
    let index = 0;
    while (index < tokens.length) {
      const { token, info } = tokens[index];

      if (info.kind !== 'option') {
        extras.push(token);
        index += 1;
        continue;
      }

      if (info.action.nargs === 0) {
        if (info.explicitArg !== null) {
          throw new ArgumentError(
            info.action.name,
            `ignored explicit argument ${pyStrRepr(info.explicitArg)}`,
          );
        }
        // The only zero-argument action here is --help.
        this.printHelp();
        throw new SystemExit(0);
      }

      let rawValue;
      if (info.explicitArg !== null) {
        rawValue = info.explicitArg;
        index += 1;
      } else {
        const next = tokens[index + 1];
        if (!next || next.info.kind !== 'value') {
          this.error(`argument ${info.optionString}: expected one argument`);
        }
        rawValue = next.token;
        index += 2;
      }

      namespace[info.action.dest] = this.convert(info.action, rawValue);
      seen.add(info.action);
    }

    // Required options are reported before unrecognized ones.
    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /** `parse_args`. Defaults to the arguments this process was started with. */
  parseArgs(argv = process.argv.slice(2)) {
    try {
      const [namespace, extras] = this.parseKnownArgs(argv);
      if (extras.length > 0) {
        this.error(`unrecognized arguments: ${extras.join(' ')}`);
      }
      return namespace;
    } catch (cause) {
      if (cause instanceof ArgumentError) this.error(cause.message);
      throw cause;
    }
  }
}

export { SystemExit, printLine };

