/**
 * Reproduces the traceback CPython prints for an unhandled exception, so that a
 * non-ASCII `--a` fails the same way (empty stdout, message on stderr, exit 1)
 * as the reference program.
 */

import { writeStderr } from './io.mjs';

/**
 * @param {Error} error the exception that escaped
 * @param {{file: string, line: number, scope: string, source: string, marked: string}} frame
 *   the source location to attribute it to; `marked` is the sub-expression the
 *   caret line should underline.
 */
export function printTraceback(error, frame) {
  const caretOffset = frame.source.indexOf(frame.marked);
  const indent = ' '.repeat(4 + (caretOffset < 0 ? 0 : caretOffset));

  writeStderr('Traceback (most recent call last):\n');
  writeStderr(`  File "${frame.file}", line ${frame.line}, in ${frame.scope}\n`);
  writeStderr(`    ${frame.source}\n`);
  writeStderr(`${indent}${'^'.repeat(frame.marked.length)}\n`);
  writeStderr(`${error.name}: ${error.message}\n`);
}

