/**
 * Node.js port of dataset/bencoder/test6.py
 *
 *   import argparse
 *   import bencoder
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   parser.add_argument('--b', type=int, required=True)
 *   args = parser.parse_args()
 *
 *   list_data = [args.a.encode('ascii'), args.b, [args.b]]
 *   encoded = bencoder.encode(list_data)   # Encode nested list
 *   decoded = bencoder.decode(encoded)     # Decode the encoded data
 *   print(encoded)
 *   print(decoded)
 */

import { ArgumentParser, STR_TYPE, INT_TYPE } from './lib/cli/argparse.mjs';
import { SystemExit } from './lib/cli/errors.mjs';
import { printTraceback } from './lib/cli/traceback.mjs';
import { printLine } from './lib/cli/io.mjs';
import { encodeAscii, UnicodeEncodeError } from './lib/pytypes/bytes.mjs';
import { pyRepr } from './lib/pytypes/repr.mjs';
import { encode, decode } from './lib/bencode/index.mjs';

const SOURCE_LINE = {
  file: 'test6.py',
  line: 9,
  scope: '<module>',
  source: 'list_data = [args.a.encode(\'ascii\'), args.b, [args.b]]',
  marked: "args.a.encode('ascii')",
};

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: STR_TYPE, required: true });
  parser.addArgument('--b', { type: INT_TYPE, required: true });
  const args = parser.parseArgs();

  let listData;
  try {
    listData = [encodeAscii(args.a), args.b, [args.b]];
  } catch (cause) {
    if (cause instanceof UnicodeEncodeError) {
      printTraceback(cause, SOURCE_LINE);
      throw new SystemExit(1);
    }
    throw cause;
  }

  const encoded = encode(listData); // Encode nested list
  const decoded = decode(encoded); // Decode the encoded data
  printLine(pyRepr(encoded));
  printLine(pyRepr(decoded));
}

try {
  main();
} catch (cause) {
  if (cause instanceof SystemExit) process.exit(cause.code);
  throw cause;
}

