/**
 * Synchronous stdout/stderr writes.
 *
 * `console.log` on a pipe is asynchronous in Node, so output can be lost when
 * the process exits right afterwards (which argparse errors do). Writing
 * through `fs.writeSync` keeps ordering and exit codes reliable.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

function write(fd, text) {
  if (text === '') return;
  let written = 0;
  const payload = text;
  // Short writes are possible on pipes; loop until the buffer is drained.
  while (written < payload.length) {
    written += writeSync(fd, payload.slice(written));
  }
}

/** `print(text)` — appends the trailing newline. */
export function printLine(text) {
  write(STDOUT_FD, `${text}\n`);
}

export function writeStdout(text) {
  write(STDOUT_FD, text);
}

export function writeStderr(text) {
  write(STDERR_FD, text);
}

/**
 * Bencode encoder.
 *
 * The four bencode types map onto the Python values as follows:
 *   bytes -> `<length>:<payload>`
 *   int   -> `i<decimal>e`
 *   list  -> `l<items>e`
 *   dict  -> `d<key/value pairs>e`, keys sorted bytewise
 */

import { PyBytes, isPyBytes, bytesFromLatin1, concatBytes } from '../pytypes/bytes.mjs';
import { isPyInt } from '../pytypes/int.mjs';

/** Raised for values bencode has no representation for. */
export class BencodeEncodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BencodeEncodeError';
  }
}

function encodeBytes(value) {
  return concatBytes([bytesFromLatin1(`${value.length}:`), value]);
}

function encodeInt(value) {
  return bytesFromLatin1(`i${value.toString()}e`);
}

function encodeList(items) {
  return concatBytes([
    bytesFromLatin1('l'),
    ...items.map((item) => encode(item)),
    bytesFromLatin1('e'),
  ]);
}

function encodeDict(entries) {
  const sorted = [...entries].sort((left, right) =>
    compareBytes(left[0], right[0]),
  );
  return concatBytes([
    bytesFromLatin1('d'),
    ...sorted.flatMap(([key, item]) => [encodeBytes(key), encode(item)]),
    bytesFromLatin1('e'),
  ]);
}

function compareBytes(left, right) {
  const shared = Math.min(left.length, right.length);
  for (let index = 0; index < shared; index += 1) {
    const difference = left.at(index) - right.at(index);
    if (difference !== 0) return difference;
  }
  return left.length - right.length;
}

/**
 * Encodes a value into a `PyBytes`.
 *
 * @param {PyBytes|bigint|Array|Map} value
 * @returns {PyBytes}
 */
export function encode(value) {
  if (isPyBytes(value)) return encodeBytes(value);
  if (isPyInt(value)) return encodeInt(value);
  if (Array.isArray(value)) return encodeList(value);
  if (value instanceof Map) return encodeDict([...value.entries()]);
  throw new BencodeEncodeError(`Cannot encode value of type ${typeof value}`);
}

/**
 * A faithful-enough `argparse.ArgumentParser` for this program's interface:
 * two required options taking one value each, plus the automatic `-h/--help`.
 *
 * The behaviours that matter for output parity, all verified against the
 * reference build:
 *   - `--opt value` and `--opt=value` are both accepted
 *   - unambiguous long-option prefixes are accepted (`--he` -> `--help`)
 *   - a later occurrence of an option overwrites an earlier one
 *   - tokens are classified as option-vs-value in one pass up front, so
 *     `--a -x` fails with "expected one argument" while `--a -5` succeeds
 *   - missing required options are reported before unrecognized ones
 *   - errors print usage plus `prog: error: ...` on stderr and exit 2
 */

import { basename } from 'node:path';
import { pyStrRepr } from '../pytypes/escape.mjs';
import { pyIntFromString, PyValueError } from '../pytypes/int.mjs';
import { ArgumentError, SystemExit } from './errors.mjs';
import { printLine, writeStdout, writeStderr } from './io.mjs';

const PREFIX_CHARS = '-';
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
const MAX_HELP_POSITION = 24;
const INDENT = 2;

/** argparse's `type=int`, reported as `int` in error messages. */
export const INT_TYPE = { name: 'int', convert: pyIntFromString };

/** argparse's `type=str`, which is the identity conversion. */
export const STR_TYPE = { name: 'str', convert: (text) => text };

class Action {
  constructor({ optionStrings, dest, type, required, nargs, help }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.nargs = nargs;
    this.help = help;
    this.metavar = dest.toUpperCase();
  }

  /** `_get_action_name`: how the action is named inside error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** `--a A`, or `-h, --help` for the flag that takes no value. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${this.metavar}`).join(', ');
  }

  /** How the action appears inside the usage line. */
  formatUsage() {
    const primary = this.optionStrings[0];
    const body = this.nargs === 0 ? primary : `${primary} ${this.metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  constructor({ prog } = {}) {
