   * `_parse_optional`: decides whether a token is an option, and if so which
   * action it names and whether a value was glued on with `=`.
   */
  classifyToken(token) {
    if (token === '') return { kind: 'value' };
    if (!PREFIX_CHARS.includes(token[0])) return { kind: 'value' };

    const exact = this.optionStringActions.get(token);
    if (exact) return { kind: 'option', action: exact, optionString: token, explicitArg: null };

    // A lone "-" is a positional by convention.
    if (token.length === 1) return { kind: 'value' };

    if (token.includes('=')) {
      const separator = token.indexOf('=');
      const optionString = token.slice(0, separator);
      const action = this.optionStringActions.get(optionString);
      if (action) {
        return { kind: 'option', action, optionString, explicitArg: token.slice(separator + 1) };
      }
    }

    const matches = this.matchAbbreviation(token);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    // Negative numbers are values as long as no option looks like one.
    if (NEGATIVE_NUMBER.test(token)) return { kind: 'value' };
    if (token.includes(' ')) return { kind: 'value' };

    return { kind: 'unknown-option' };
  }

  /** `_get_option_tuples`: long options may be abbreviated to a unique prefix. */
  matchAbbreviation(token) {
    if (!(PREFIX_CHARS.includes(token[0]) && PREFIX_CHARS.includes(token[1]))) return [];

    const separator = token.indexOf('=');
    const prefix = separator === -1 ? token : token.slice(0, separator);
    const explicitArg = separator === -1 ? null : token.slice(separator + 1);

    const matches = [];
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(prefix)) {
        matches.push({ kind: 'option', action, optionString, explicitArg });
      }
    }
    return matches;
  }

